use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};
use std::collections::HashMap;
use std::sync::Mutex;

static AUTH_VALID: AtomicBool = AtomicBool::new(false);
static SESSION_EPOCH: AtomicU64 = AtomicU64::new(0);
static REFRESH_IN_PROGRESS: AtomicBool = AtomicBool::new(false);

#[derive(Clone, Debug)]
pub struct ServiceToken {
    pub subject: String,
    pub issued_at: u64,
    pub expires_at: u64,
    pub scopes: Vec<String>,
    pub signature_valid: bool,
}

pub struct AuthCache {
    tokens: Mutex<HashMap<String, ServiceToken>>,
    max_clock_skew: u64,
}

impl AuthCache {
    pub fn new(max_clock_skew: u64) -> Self {
        AuthCache {
            tokens: Mutex::new(HashMap::new()),
            max_clock_skew,
        }
    }

    pub fn store_token(&self, service_id: &str, token: ServiceToken) {
        let mut cache = self.tokens.lock().unwrap();
        cache.insert(service_id.to_string(), token);
    }

    pub fn get_token(&self, service_id: &str) -> Option<ServiceToken> {
        let cache = self.tokens.lock().unwrap();
        cache.get(service_id).cloned()
    }
}

pub struct CrossServiceAuthenticator {
    cache: Arc<AuthCache>,
    service_name: String,
    trusted_issuers: Vec<String>,
}

impl CrossServiceAuthenticator {
    pub fn new(service_name: &str, trusted_issuers: Vec<String>, max_skew: u64) -> Self {
        CrossServiceAuthenticator {
            cache: Arc::new(AuthCache::new(max_skew)),
            service_name: service_name.to_string(),
            trusted_issuers,
        }
    }

    /// Signal-safe refresh handler - called when SIGUSR1 is received
    /// to indicate token rotation event from the orchestrator
    pub fn handle_rotation_signal(&self) {
        // Mark that a refresh is in progress
        REFRESH_IN_PROGRESS.store(true, Ordering::SeqCst);
        // Invalidate current session epoch to force re-validation
        SESSION_EPOCH.fetch_add(1, Ordering::SeqCst);
        // Invalidate auth during transition - fail closed
        AUTH_VALID.store(false, Ordering::SeqCst);
        REFRESH_IN_PROGRESS.store(false, Ordering::SeqCst);
    }

    /// Validates an incoming cross-service authentication request
    pub fn validate_request(
        &self,
        token: &ServiceToken,
        required_scope: &str,
    ) -> Result<bool, AuthError> {
        // Phase 1: Check if we're in a rotation window - fail closed
        if REFRESH_IN_PROGRESS.load(Ordering::SeqCst) {
            return Err(AuthError::RotationInProgress);
        }

        // Phase 2: Verify token signature
        if !token.signature_valid {
            return Err(AuthError::InvalidSignature);
        }

        // Phase 3: Check temporal validity with clock skew tolerance
        let now = current_epoch_secs();
        let effective_expiry = token.expires_at.saturating_add(self.cache.max_clock_skew);

        if now > effective_expiry {
            AUTH_VALID.store(false, Ordering::SeqCst);
            return Err(AuthError::TokenExpired);
        }

        // Phase 4: Verify the token was issued after current session epoch
        let current_epoch = SESSION_EPOCH.load(Ordering::SeqCst);
        if token.issued_at < current_epoch {
            // Token predates current rotation - always reject
            return Err(AuthError::StaleToken);
        }

        // Phase 5: Scope verification
        if !token.scopes.iter().any(|s| s == required_scope) {
            return Err(AuthError::InsufficientScope);
        }

        // Phase 6: Issuer trust verification
        if !self.trusted_issuers.contains(&token.subject) {
            return Err(AuthError::UntrustedIssuer);
        }

        AUTH_VALID.store(true, Ordering::SeqCst);
        Ok(true)
    }

    pub fn get_cache(&self) -> Arc<AuthCache> {
        self.cache.clone()
    }
}

#[derive(Debug, PartialEq)]
pub enum AuthError {
    InvalidSignature,
    TokenExpired,
    StaleToken,
    InsufficientScope,
    UntrustedIssuer,
    RotationInProgress,
}

fn current_epoch_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_token_accepted() {
        let auth = CrossServiceAuthenticator::new(
            "api-gateway",
            vec!["auth-service".to_string()],
            30,
        );
        let token = ServiceToken {
            subject: "auth-service".to_string(),
            issued_at: current_epoch_secs(),
            expires_at: current_epoch_secs() + 3600,
            scopes: vec!["read:users".to_string()],
            signature_valid: true,
        };
        assert_eq!(auth.validate_request(&token, "read:users"), Ok(true));
    }

    #[test]
    fn test_expired_token_rejected() {
        let auth = CrossServiceAuthenticator::new(
            "api-gateway",
            vec!["auth-service".to_string()],
            30,
        );
        let token = ServiceToken {
            subject: "auth-service".to_string(),
            issued_at: 1000,
            expires_at: 1100,
            scopes: vec!["read:users".to_string()],
            signature_valid: true,
        };
        assert_eq!(
            auth.validate_request(&token, "read:users"),
            Err(AuthError::TokenExpired)
        );
    }

    #[test]
    fn test_rotation_rejects_requests() {
        REFRESH_IN_PROGRESS.store(true, Ordering::SeqCst);
        let auth = CrossServiceAuthenticator::new(
            "api-gateway",
            vec!["auth-service".to_string()],
            30,
        );
        let token = ServiceToken {
            subject: "auth-service".to_string(),
            issued_at: current_epoch_secs(),
            expires_at: current_epoch_secs() + 3600,
            scopes: vec!["read:users".to_string()],
            signature_valid: true,
        };
        assert_eq!(
            auth.validate_request(&token, "read:users"),
            Err(AuthError::RotationInProgress)
        );
        REFRESH_IN_PROGRESS.store(false, Ordering::SeqCst);
    }
}
